    "app/globals.css": "/* ============================================================\n   THEME TOKENS — the customization surface. Change a value\n   here and the whole dashboard re-skins. No markup edits.\n   ============================================================ */\n:root {\n  --bg: #f6f7f9;\n  --surface: #ffffff;\n  --text: #14181f;\n  --muted: #5b6472;\n  --border: #e4e7ec;\n  --primary: #2f6df6;\n  --primary-text: #ffffff;\n  --good: #16a34a;\n  --bad: #dc2626;\n  --radius: 12px;\n  --sidebar-w: 220px;\n  --font: ui-sans-serif, system-ui, -apple-system, \"Segoe UI\", Roboto, sans-serif;\n}\n\n* { box-sizing: border-box; margin: 0; padding: 0; }\nhtml, body { height: 100%; }\nbody { font-family: var(--font); background: var(--bg); color: var(--text); }\na { color: inherit; text-decoration: none; }\n\n.layout { display: flex; min-height: 100vh; }\n.main { flex: 1; padding: 28px 32px; }\n.muted { color: var(--muted); }\n\n.h1 { font-size: 1.5rem; letter-spacing: -0.02em; margin-bottom: 4px; }\n.h2 { font-size: 1.05rem; margin-bottom: 14px; }\n\n.grid { display: grid; gap: 16px; grid-template-columns: repeat(auto-fit, minmax(190px, 1fr)); }\n.card {\n  background: var(--surface);\n  border: 1px solid var(--border);\n  border-radius: var(--radius);\n  padding: 18px;\n}\n\n.btn {\n  display: inline-block;\n  padding: 10px 18px;\n  border-radius: var(--radius);\n  background: var(--primary);\n  color: var(--primary-text);\n  font-weight: 600;\n  border: 1px solid transparent;\n  cursor: pointer;\n  font-size: 0.95rem;\n}\n.btn-ghost { background: transparent; color: var(--text); border-color: var(--border); }\n\n.field { display: flex; flex-direction: column; gap: 6px; margin-bottom: 14px; }\n.field label { font-size: 0.85rem; font-weight: 600; color: var(--muted); }\n.field input {\n  padding: 10px 12px;\n  border: 1px solid var(--border);\n  border-radius: var(--radius);\n  font: inherit;\n  background: var(--surface);\n  color: var(--text);\n}\n\ntable { width: 100%; border-collapse: collapse; }\nth, td { text-align: left; padding: 12px 14px; border-bottom: 1px solid var(--border); font-size: 0.92rem; }\nth { color: var(--muted); font-weight: 600; font-size: 0.8rem; text-transform: uppercase; letter-spacing: 0.04em; }\n\n.pill { font-size: 0.78rem; font-weight: 600; padding: 3px 10px; border-radius: 999px; }\n.pill-Active { background: #dcfce7; color: #166534; }\n.pill-Trial { background: #fef9c3; color: #854d0e; }\n.pill-Churned { background: #fee2e2; color: #991b1b; }\n",
