    "app/settings/page.tsx": "import { Shell } from '@/components/Shell'\nimport { site } from '@/lib/site'\n\nexport default function SettingsPage() {\n  return (\n    <Shell>\n      <h1 className=\"h1\">Settings</h1>\n      <p className=\"muted\" style={{ marginBottom: 22 }}>\n        Manage your workspace.\n      </p>\n\n      <div className=\"card\" style={{ maxWidth: 460 }}>\n        <h2 className=\"h2\">Workspace</h2>\n        <div className=\"field\">\n          <label htmlFor=\"name\">Workspace name</label>\n          <input id=\"name\" name=\"name\" defaultValue={site.name} />\n        </div>\n        <div className=\"field\">\n          <label htmlFor=\"email\">Billing email</label>\n          <input id=\"email\" name=\"email\" type=\"email\" placeholder=\"you@example.com\" />\n        </div>\n        <button className=\"btn\" type=\"button\">Save changes</button>\n      </div>\n    </Shell>\n  )\n}\n",
    "components/DataTable.tsx": "import type { Row } from '@/lib/site'\n\nexport function DataTable({ rows }: { rows: Row[] }) {\n  return (\n    <div className=\"card\" style={{ padding: 0, overflow: 'hidden' }}>\n      <table>\n        <thead>\n          <tr>\n            <th>Name</th>\n            <th>Email</th>\n            <th>Plan</th>\n            <th>Status</th>\n          </tr>\n        </thead>\n        <tbody>\n          {rows.map((r) => (\n            <tr key={r.email}>\n              <td style={{ fontWeight: 600 }}>{r.name}</td>\n              <td className=\"muted\">{r.email}</td>\n              <td>{r.plan}</td>\n              <td><span className={`pill pill-${r.status}`}>{r.status}</span></td>\n            </tr>\n          ))}\n        </tbody>\n      </table>\n    </div>\n  )\n}\n",
