    "components/StatCard.tsx": "import type { Stat } from '@/lib/site'\n\nexport function StatCard({ stat }: { stat: Stat }) {\n  const positive = stat.delta.trim().startsWith('+')\n  return (\n    <div className=\"card\">\n      <div className=\"muted\" style={{ fontSize: '0.85rem' }}>{stat.label}</div>\n      <div style={{ fontSize: '1.6rem', fontWeight: 700, margin: '6px 0 2px' }}>\n        {stat.value}\n      </div>\n      <div style={{ fontSize: '0.85rem', fontWeight: 600, color: positive ? 'var(--good)' : 'var(--bad)' }}>\n        {stat.delta}\n      </div>\n    </div>\n  )\n}\n",
